"""PSLE-style items for sci-systems-circuit (file sci-circuit.json), all tiers (round sci-fill-circuit-2026-11-20)."""
from fillkit import add, table, lint
from figs_circuit import circuit

SUB, FILE = "sci-systems-circuit", "sci-circuit.json"
CB, FT, RD = "sci-pat-circuit-basics", "sci-pat-fair-test-design", "sci-pat-read-data"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append(a)
def W(t, tag, why): return (t, tag, why)
def tb(h, r, w, c): return lambda: table(h, r, w, c)
def ser(sw=True, lit=None, bat=1, cap="A circuit"): return lambda: circuit([[("L", "P", lit)], [("S", "S", sw), ("B", bat)]], caption=cap)

# ---------------- basic ----------------
q("ci-001", B, 1, CB, "Which part of a circuit provides the electrical energy?", "The battery", [W("The switch", "wrong-part", "A switch only opens or closes the circuit."), W("The bulb", "wrong-part", "The bulb changes electrical energy into light and heat."), W("The wire", "wrong-part", "Wires carry the electricity. They do not provide the energy.")], ["A battery is the energy source."], None)
q("ci-002", B, 1, CB, "What is the job of a switch in a circuit?", "To open or close the circuit", [W("To provide electrical energy", "wrong-job", "The battery does this."), W("To give out light", "wrong-job", "The bulb does this."), W("To make the wire hot", "wrong-job", "A switch does not heat the wire.")], ["A switch opens or closes the path for the electricity."], None)
q("ci-003", B, 2, CB, "A circuit has a battery, a bulb, a switch and wires joined in a loop. When will the bulb light up?", "When the switch is closed", [W("When the switch is open", "reversed", "An open switch breaks the circuit."), W("Only when the wires are touching the table", "wrong-idea", "The table has nothing to do with it."), W("Only when two switches are used", "wrong-idea", "One closed switch is enough.")], ["The bulb lights when the circuit is complete and closed."], None)
q("ci-004", B, 2, CB, "Look at the circuit. Will the bulb light up?", "Yes, because the circuit is closed", [W("No, because there is only one bulb", "wrong-reason", "One bulb is enough."), W("No, because the switch is in the wrong place", "wrong-reason", "A switch can be anywhere in the loop."), W("No, because there is no wire", "wrong-reason", "The wires are drawn as lines.")], ["The path is complete, so current flows and the bulb lights."], ser(True))
q("ci-005", B, 2, CB, "Look at the circuit. The bulb does not light up. Why?", "The switch is open, so the circuit is not complete", [W("The battery is too big", "wrong-reason", "A battery cannot be too big."), W("The bulb is in the wrong place", "wrong-reason", "A bulb can be anywhere in the loop."), W("The wires are too short", "wrong-reason", "The wire length is not the problem.")], ["An open switch leaves a gap, so no current flows."], ser(False))
q("ci-006", B, 1, CB, "Look at the circuit. The bulb does not light up when the switch is closed. Which part is missing?", "A battery", [W("A second bulb", "wrong-part", "One bulb does not need a second bulb."), W("A second switch", "wrong-part", "One closed switch is enough."), W("A bigger bulb", "wrong-part", "The circuit has no energy source.")], ["Without a battery there is no energy source."], lambda: circuit([[("L", "P")], [("S", "S", True)]], caption="A circuit"))
q("ci-007", B, 2, CB, "What happens to the current when a switch in a circuit is opened?", "The current stops flowing", [W("The current flows faster", "wrong-idea", "Opening the circuit stops the current."), W("The current flows the other way", "wrong-idea", "The current does not reverse."), W("The current does not change", "wrong-idea", "An open switch breaks the circuit.")], ["An open switch breaks the path, so there is no current."], None)
q("ci-008", B, 1, CB, "Which of the following is the best material for the wires of a circuit?", "Copper", [W("Plastic", "wrong-material", "Plastic is an insulator."), W("Rubber", "wrong-material", "Rubber is an insulator."), W("Wood", "wrong-material", "Wood is an insulator.")], ["Copper is a metal and a good conductor of electricity."], None)
q("ci-009", B, 2, CB, "A student connects a bulb to a battery using a plastic string instead of a wire. The bulb does not light. Why?", "Plastic does not let electricity pass through it", [W("The string is too thin", "wrong-reason", "Thickness is not the reason."), W("The battery is too weak", "wrong-reason", "The battery is fine. The plastic is the problem."), W("The bulb is too bright", "wrong-reason", "The bulb never lit.")], ["Plastic is an insulator, so the circuit is not complete."], None)
q("ci-010", B, 2, CB, "Look at the circuit. The bulb does not light. Which action will make it light?", "Closing the switch", [W("Adding a second switch", "wrong-action", "A second switch would not close the gap."), W("Taking out the battery", "wrong-action", "Without a battery nothing would light."), W("Turning the bulb upside down", "wrong-action", "This does not close the gap in the circuit.")], ["Closing the switch completes the circuit."], ser(False))
q("ci-011", B, 2, CB, "Switch S is closed. Which bulbs will light up?", "Both P and Q", [W("P only", "wrong-bulb", "Current goes through both bulbs in the loop."), W("Q only", "wrong-bulb", "Current goes through both bulbs in the loop."), W("Neither P nor Q", "wrong-bulb", "The circuit is closed, so current flows.")], ["The circuit is complete, so both bulbs light."], lambda: circuit([[("L", "P"), ("L", "Q")], [("S", "S", True), ("B", 2)]], caption="A circuit"))
q("ci-012", B, 2, CB, "Switch S is open. Which bulbs will light up?", "Neither P nor Q", [W("P only", "wrong-bulb", "An open switch stops current to every part."), W("Q only", "wrong-bulb", "An open switch stops current to every part."), W("Both P and Q", "wrong-bulb", "An open switch breaks the circuit.")], ["The open switch breaks the only path."], lambda: circuit([[("L", "P"), ("L", "Q")], [("S", "S", False), ("B", 2)]], caption="A circuit"))
q("ci-013", B, 2, CB, "In the circuit shown, switch S1 is closed and switch S2 is open. Which bulb lights up?", "P only", [W("Q only", "wrong-bulb", "Q's branch has the open switch."), W("Both P and Q", "wrong-bulb", "Q's branch is open."), W("Neither P nor Q", "wrong-bulb", "P is on a complete path.")], ["P is on a complete path. Q's branch is broken by S2."], lambda: circuit(main=("S", "S1", True), rows=[[("L", "P")], [("L", "Q"), ("S", "S2", False)], [("B", 2)]], caption="A circuit", W=320))
q("ci-014", B, 1, CB, "What is a closed circuit?", "A complete path that current can flow around", [W("A circuit with a gap in it", "reversed", "That is an open circuit."), W("A circuit with no battery", "wrong-idea", "Without a battery nothing flows."), W("A circuit with only a switch", "wrong-idea", "A circuit needs more than a switch.")], ["A closed circuit has no gaps."], None)
q("ci-015", B, 2, CB, "Why are electric wires covered with plastic?", "Plastic is an insulator, so it keeps us safe from the electricity", [W("Plastic is a good conductor", "reversed", "Plastic is an insulator."), W("Plastic makes the wire carry more electricity", "wrong-idea", "It does not."), W("Plastic makes the wire lighter", "wrong-idea", "Weight is not the reason.")], ["The plastic does not let electricity pass to our hands."], None)
