EDIT = {
    "ci-005": {'The switch is open, so the circuit is not complete': 'The open switch breaks the circuit', 'The bulb is in the wrong place': 'The bulb is in the wrong place in the loop', 'The battery is too big': 'The battery is too big for the bulb'},
    "ci-009": {'Plastic does not let electricity pass through it': 'Plastic does not conduct electricity', 'The string is too thin': 'The string is too thin to carry any current', 'The battery is too weak': 'The battery is too weak to light the bulb', 'The bulb is too bright': 'The bulb is too big for the battery'},
    "ci-014": {'A complete path that current can flow around': 'A complete path for the current', 'A circuit with a gap in it': 'A circuit that has a gap in it', 'A circuit with no battery': 'A circuit that has no battery', 'A circuit with only a switch': 'A circuit that has only a switch'},
    "ci-015": {'Plastic is an insulator, so it keeps us safe from the electricity': 'Plastic is an insulator, so we stay safe', 'Plastic is a good conductor': 'Plastic is a good conductor of electricity'},
    "ci-018": {'Two bulbs in the same circuit': 'Two bulbs in the same circuit loop'},
    "ci-019": {'The bulb does not light because the circuit is broken at the bulb': 'It stays off, as the circuit is broken', 'The bulb lights up brightly': 'The bulb lights up brightly at first', 'The bulb lights up dimly': 'The bulb lights up only very dimly', 'The battery gets bigger': 'The battery gets bigger and hotter'},
    "ci-025": {'Nothing will happen': 'Nothing will happen to the bulb or the battery'},
    "ci-112": {'Yes, it works only next to the battery': 'Yes, it works only when it is next to the battery'},
    "ci-119": {'It makes the electricity': 'It makes the electricity for the bulb'},
    "ci-205": {'If any one bulb is fused, all three go out': 'If one bulb is fused, all three go out', 'Each bulb works on its own': 'Each bulb works on its own path now', 'If R is fused, P and Q stay lit': 'If R is fused, P and Q both stay lit'},
    "ci-206": {'One of the wires is not touching the metal part of its terminal': 'A wire is not touching its terminal'},
    "ci-209": {'Put the lead in the gap of a circuit with a battery and a bulb': 'Put it in the gap of a circuit with a bulb'},
    "ci-214": {'Whether the metal parts of the circuit are touching one another': 'Whether the metal parts touch', 'Whether the torch is heavy': 'Whether the torch is heavy to hold', 'Whether the case is red': 'Whether the case is painted red', 'Whether the torch is new': 'Whether the torch was bought new'},
    "ci-215": {'R still has a complete path if P or Q is fused': 'R still has its own complete path', 'P still lights if Q is fused': 'P still lights if Q is fused or removed'},
    "ci-223": {'A wire joins one end of the battery to the bulb and another wire joins the bulb to the other end of the battery': 'Two wires join the bulb to both ends of the battery'},
    "ci-217": {'Graphite is a conductor even though it is not a metal': 'Graphite conducts even though it is not a metal'},
}
def _apply():
    out = []
    for r in P:
        m = EDIT.get(r[0])
        if m:
            r = list(r)
            if r[5] in m: r[5] = m[r[5]]
            r[6] = [(m.get(w[0], w[0]),) + tuple(w[1:]) for w in r[6]]
            r = tuple(r)
        out.append(r)
    return out

if __name__ == "__main__":
    print("added", add(SUB, FILE, _apply()))
    lint(SUB, FILE, "ci-")
